//! Explicit per-user managed native collections. Invoke filesystem methods only
//! on the existing I/O owner. Arbitrary Open paths never become owned entries.
use crate::storage::{self,LoadedDocument,SaveJob,SaveReceipt,SavedFileStamp,Phase};
use skylive_core::{Session,StudioSnapshot,Collection,Command,Id};
use serde::{Serialize,Deserialize};
use std::{fmt,fs::{self,File},io::{self,Read},path::{Path,PathBuf},sync::{Arc,atomic::{AtomicUsize,Ordering}}};
#[cfg(target_os="windows")]use std::fs::OpenOptions;
pub const MAX_COLLECTIONS:usize=64;pub const MAX_INDEX_BYTES:usize=128*1024;
pub const MAX_CREATE_METADATA_BYTES:usize=192*1024*1024;
static CREATE_BYTES:AtomicUsize=AtomicUsize::new(0);
struct CreateCredit{bytes:usize}
impl Drop for CreateCredit{fn drop(&mut self){CREATE_BYTES.fetch_sub(self.bytes,Ordering::AcqRel);}}
/// Cooperative extra-copy/scratch charge, retained through pending publication.
/// Canonical current-document storage and OS allocator overhead are separate.
#[derive(Clone)]pub struct CreationLease{_credit:Arc<CreateCredit>}
fn admit_create(plan:&CreatePlan)->Result<CreationLease,Error>{
 struct Count(usize);impl std::io::Write for Count{fn write(&mut self,bytes:&[u8])->io::Result<usize>{self.0=self.0.checked_add(bytes.len()).filter(|bytes|*bytes<=12*1024*1024).ok_or_else(||io::Error::other("managed duplicate metadata exceeds 12 MiB serialized preflight"))?;Ok(bytes.len())}fn flush(&mut self)->io::Result<()>{Ok(())}}
 let mut count=Count(0);if plan.duplicate{serde_json::to_writer(&mut count,&*plan.model)}else{serde_json::to_writer(&mut count,&(plan.model.profiles(),plan.model.preferences()))}.map_err(|error|reject("collection_metadata_budget",error))?;
 let (sources,scenes,items)=if plan.duplicate{(plan.model.sources().len(),plan.model.scenes().len()+plan.model.groups().len(),plan.model.scenes().iter().chain(plan.model.groups()).map(|scene|scene.items().len()).sum::<usize>())}else{(0,1,0)};
 let structural=sources.checked_mul(4*std::mem::size_of::<skylive_core::Source>()).and_then(|value|value.checked_add(scenes*4*std::mem::size_of::<skylive_core::Scene>())).and_then(|value|value.checked_add(items*4*std::mem::size_of::<skylive_core::SceneItem>())).ok_or_else(||reject("collection_metadata_budget","metadata structure charge overflow"))?;
 let bytes=count.0.checked_mul(8).and_then(|value|value.checked_add(structural)).and_then(|value|value.checked_add(storage::MAX_FILE_BYTES as usize+2*MAX_INDEX_BYTES)).ok_or_else(||reject("collection_metadata_budget","metadata charge overflow"))?;
 CREATE_BYTES.fetch_update(Ordering::AcqRel,Ordering::Acquire,|used|used.checked_add(bytes).filter(|total|*total<=MAX_CREATE_METADATA_BYTES)).map_err(|_|reject("collection_metadata_budget","managed creation current/retiring metadata budget 192 MiB is occupied"))?;
 Ok(CreationLease{_credit:Arc::new(CreateCredit{bytes})})
}

#[derive(Clone,Copy,Debug,PartialEq,Eq,Hash,Serialize,Deserialize)]#[serde(try_from="u64",into="u64")]
pub struct EntryId(u64);
impl EntryId{pub fn new(value:u64)->Result<Self,Error>{if value==0||value==u64::MAX{Err(reject("collection_id","collection identity is not valid"))}else{Ok(Self(value))}}pub fn get(self)->u64{self.0}}
impl TryFrom<u64> for EntryId{type Error=Error;fn try_from(value:u64)->Result<Self,Error>{Self::new(value)}}impl From<EntryId> for u64{fn from(value:EntryId)->u64{value.0}}
#[derive(Clone,Debug,PartialEq,Eq,Serialize)]pub struct Root{path:PathBuf}
impl Root{
 pub fn for_preferences(path:&Path)->Result<Self,Error>{if !path.is_absolute()||path.file_name().is_none(){return Err(reject("collection_root","installed settings path must be an absolute filename"));}let path=path.parent().ok_or_else(||reject("collection_root","settings parent is unavailable"))?.join("collections");validate_absolute(&path)?;Ok(Self{path})}
 pub fn path(&self)->&Path{&self.path}
 fn actual(&self,create:bool)->Result<Option<PathBuf>,Error>{if create{write_capability()?;fs::create_dir_all(&self.path).map_err(io_before)?;}let path=match fs::canonicalize(&self.path){Ok(value)=>value,Err(error)if !create&&error.kind()==io::ErrorKind::NotFound=>return Ok(None),Err(error)=>return Err(io_before(error))};validate_absolute(&path)?;if !path.is_dir(){return Err(reject("collection_root","managed collection root is not a directory"));}Ok(Some(path))}
}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Entry{pub id:EntryId,pub name:String}
#[derive(Clone,Debug,Serialize)]pub struct View{root:Root,pub version:u64,pub entries:Vec<Entry>,pub writable:bool}
impl View{pub fn root(&self)->&Root{&self.root}pub fn entry(&self,id:EntryId)->Option<&Entry>{self.entries.iter().find(|entry|entry.id==id)}pub fn path_for(&self,id:EntryId)->Option<PathBuf>{self.entry(id).map(|_|entry_path(&self.root.path,id))}}
#[derive(Serialize,Deserialize)]#[serde(deny_unknown_fields)]struct Index{schema:u32,version:u64,next_id:u64,entries:Vec<Entry>}
impl Default for Index{fn default()->Self{Self{schema:1,version:0,next_id:1,entries:Vec::new()}}}
impl Index{
 fn validate(&self)->Result<(),Error>{if self.schema!=1||self.next_id==0||self.entries.len()>MAX_COLLECTIONS{return Err(reject("collection_index","unsupported index version or collection count"));}let mut ids=std::collections::HashSet::new();let mut names=std::collections::HashSet::new();for entry in &self.entries{validate_name(&entry.name)?;if entry.id.0>=self.next_id||!ids.insert(entry.id)||!names.insert(entry.name.as_str()){return Err(reject("collection_index","duplicate collection identity/name or invalid issued identity"));}}Ok(())}
 fn view(&self,path:PathBuf)->View{let mut entries=self.entries.clone();entries.sort_by(|a,b|a.name.to_lowercase().cmp(&b.name.to_lowercase()).then(a.id.0.cmp(&b.id.0)));View{root:Root{path},version:self.version,entries,writable:cfg!(target_os="windows")}}
 fn bump(&mut self)->Result<(),Error>{self.version=self.version.checked_add(1).ok_or_else(||reject("collection_index","library revision is exhausted"))?;Ok(())}
}
#[derive(Debug)]pub struct Error{pub phase:Phase,code:&'static str,detail:String,pub retained:Option<PathBuf>}
impl Error{pub fn code(&self)->&'static str{self.code}}
impl fmt::Display for Error{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{write!(f,"{} ({:?}): {}",self.code,self.phase,self.detail)?;if let Some(path)=&self.retained{write!(f,"; retained artifact: {}",path.display())?;}Ok(())}}
impl std::error::Error for Error{}
fn reject(code:&'static str,detail:impl ToString)->Error{Error{phase:Phase::BeforePublication,code,detail:detail.to_string(),retained:None}}
fn io_before(error:io::Error)->Error{reject("collection_io",error)}
fn native(error:storage::StorageError)->Error{Error{phase:error.phase,code:"collection_native",detail:error.to_string(),retained:None}}
fn partial(code:&'static str,detail:impl ToString,path:PathBuf)->Error{Error{phase:Phase::AfterPublication,code,detail:detail.to_string(),retained:Some(path)}}
fn validate_name(name:&str)->Result<(),Error>{if name.trim().is_empty()||name.len()>256||name.chars().any(char::is_control){Err(reject("collection_name","collection name requires 1..256 UTF-8 bytes without controls"))}else{Ok(())}}
fn validate_absolute(path:&Path)->Result<(),Error>{if !path.is_absolute()||path.to_str().is_none_or(|text|text.len()>4096||text.chars().any(char::is_control)){Err(reject("collection_path","managed path must be absolute UTF-8, at most 4096 bytes, without controls"))}else{Ok(())}}
fn entry_path(root:&Path,id:EntryId)->PathBuf{root.join(format!("{:016x}.skylive.json",id.0))}
fn direct_child(root:&Path,path:&Path)->Result<(),Error>{validate_absolute(root)?;validate_absolute(path)?;if path.parent()!=Some(root)||path.file_name().is_none(){return Err(reject("collection_path","owned file must be a direct child of the resolved managed root"));}Ok(())}
fn regular_file(path:&Path)->Result<(),Error>{let metadata=fs::symlink_metadata(path).map_err(io_before)?;if !metadata.is_file()||metadata.file_type().is_symlink(){return Err(reject("collection_path","managed artifact must be a regular non-symlink file"));}Ok(())}
fn write_capability()->Result<(),Error>{if cfg!(target_os="windows"){Ok(())}else{Err(reject("collection_write_unavailable","managed collection writes are implemented only on Windows"))}}
struct Lock{_file:File}
impl Lock{fn acquire(root:&Path)->Result<Self,Error>{write_capability()?;let path=root.join("library.lock");direct_child(root,&path)?;match fs::symlink_metadata(&path){Ok(metadata)if !metadata.is_file()||metadata.file_type().is_symlink()=>return Err(reject("collection_lock","library lock must be a regular non-symlink file")),Ok(_)=>{},Err(error)if error.kind()==io::ErrorKind::NotFound=>{},Err(error)=>return Err(io_before(error))};
 #[cfg(target_os="windows")]{use std::os::windows::fs::OpenOptionsExt;let file=OpenOptions::new().read(true).write(true).create(true).truncate(false).share_mode(0).open(path).map_err(|error|reject("collection_library_busy",error))?;Ok(Self{_file:file})}
 #[cfg(not(target_os="windows"))]{let _=path;Err(reject("collection_write_unavailable","managed collection writes are implemented only on Windows"))}
}}
fn read_index(root:&Path)->Result<Index,Error>{let path=root.join("index.json");direct_child(root,&path)?;let mut file=match File::open(&path){Ok(file)=>{regular_file(&path)?;file},Err(error)if error.kind()==io::ErrorKind::NotFound=>return Ok(Index::default()),Err(error)=>return Err(io_before(error))};if file.metadata().map_err(io_before)?.len()>MAX_INDEX_BYTES as u64{return Err(reject("collection_index_limit","collection index exceeds 128 KiB"));}let mut bytes=vec![0;MAX_INDEX_BYTES+1];let mut count=0;while count<bytes.len(){match file.read(&mut bytes[count..]){Ok(0)=>break,Ok(n)=>count+=n,Err(error)if error.kind()==io::ErrorKind::Interrupted=>continue,Err(error)=>return Err(io_before(error))}}if count>MAX_INDEX_BYTES{return Err(reject("collection_index_limit","collection index grew beyond 128 KiB"));}let index:Index=serde_json::from_slice(&bytes[..count]).map_err(|error|reject("collection_index_decode",error))?;index.validate()?;Ok(index)}
fn publish_index(root:&Path,index:&Index)->Result<(),Error>{index.validate()?;let bytes=serde_json::to_vec_pretty(index).map_err(|error|reject("collection_index_encode",error))?;if bytes.len()>MAX_INDEX_BYTES{return Err(reject("collection_index_limit","encoded collection index exceeds 128 KiB"));}let path=root.join("index.json");direct_child(root,&path)?;storage::publish_bytes(&path,&bytes).map_err(native)}
pub fn list(root:&Root)->Result<View,Error>{match root.actual(false)?{Some(path)=>Ok(read_index(&path)?.view(path)),None=>Ok(Index::default().view(root.path.clone()))}}
pub struct CreatePlan{root:Root,model:Arc<StudioSnapshot>,preview:Id,program:Id,name:String,duplicate:bool}
impl CreatePlan{
 pub fn new(owner:&Session,view:&View,name:String,duplicate:bool,active:Option<&Path>)->Result<Self,Error>{if owner.is_closed(){return Err(reject("collection_closed","current document is closed"));}validate_name(&name)?;if owner.snapshot().name()==name&&active.is_some_and(|path|view.entries.iter().any(|entry|view.path_for(entry.id).as_deref()==Some(path))){return Err(reject("collection_name","the current managed collection already uses this canonical name"));}if view.entries.len()>=MAX_COLLECTIONS||view.entries.iter().any(|entry|entry.name==name){return Err(reject("collection_name","collection name already exists or library is full"));}if !view.writable{return Err(reject("collection_write_unavailable","managed collection writes are implemented only on Windows"));}Ok(Self{root:view.root.clone(),model:owner.snapshot(),preview:owner.preview(),program:owner.program(),name:name.into_boxed_str().into_string(),duplicate})}
 pub fn name(&self)->&str{&self.name}
}
pub struct Opened{pub loaded:Box<LoadedDocument>,pub path:PathBuf,pub view:View,pub id:EntryId,pub stamp:SavedFileStamp,creation:Option<CreationLease>}
impl Opened{pub fn take_creation_lease(&mut self)->Option<CreationLease>{self.creation.take()}}
pub fn create(plan:CreatePlan)->Result<Opened,Error>{let creation=admit_create(&plan)?;let root=plan.root.actual(true)?.ok_or_else(||reject("collection_root","managed root is unavailable"))?;let _lock=Lock::acquire(&root)?;let mut index=read_index(&root)?;if index.entries.len()>=MAX_COLLECTIONS||index.entries.iter().any(|entry|entry.name==plan.name){return Err(reject("collection_name","collection name already exists or library is full"));}let id=EntryId::new(index.next_id)?;let next=index.next_id.checked_add(1).ok_or_else(||reject("collection_id","collection identity exhausted"))?;let path=entry_path(&root,id);direct_child(&root,&path)?;index.bump()?;
 let model=if plan.duplicate{(*plan.model).clone()}else{StudioSnapshot::from_parts(0,Collection::default(),plan.model.profiles().clone(),plan.model.preferences().clone()).map_err(|error|reject("collection_snapshot",error))?};let mut session=Session::from_snapshot(model,false).map_err(|error|reject("collection_snapshot",error))?;
 if plan.duplicate{session.select_preview(plan.preview).map_err(|error|reject("collection_snapshot",error))?;session.select_program(plan.program).map_err(|error|reject("collection_snapshot",error))?;}
 session.apply(Command::RenameCollection{name:plan.name.clone()}).map_err(|error|reject("collection_name",error))?;let receipt=SaveJob::new(&session,path.clone()).run_new().map_err(|error|{let phase=error.phase;let mut problem=native(error);problem.detail.push_str(&format!("; managed target: {}",path.display()));if matches!(phase,Phase::AfterPublication){problem.retained=Some(path.clone());}problem})?;let stamp=receipt.file_stamp();if !receipt.accept(&mut session){return Err(partial("collection_receipt","created native artifact has an unexpected save receipt",path));}
 index.next_id=next;index.entries.push(Entry{id,name:plan.name});publish_index(&root,&index).map_err(|error|partial("collection_index_partial",format!("native file created; index publication failed: {error}"),path.clone()))?;
 Ok(Opened{loaded:Box::new(LoadedDocument{session,migration:storage::MigrationReport{from_schema:storage::CURRENT_SCHEMA,to_schema:storage::CURRENT_SCHEMA,scene_source_filters:Vec::new()}}),path,view:index.view(root),id,stamp,creation:Some(creation)})}
pub fn open(view:&View,id:EntryId)->Result<Opened,Error>{let root=view.root.actual(false)?.ok_or_else(||reject("collection_root","managed root is missing"))?;let index=read_index(&root)?;if !index.entries.iter().any(|entry|entry.id==id){return Err(reject("collection_stale","managed collection identity no longer exists"));}let path=entry_path(&root,id);direct_child(&root,&path)?;regular_file(&path)?;let bytes=storage::read_bytes(&path).map_err(native)?;let loaded=storage::decode_with_report(&bytes,true).map_err(native)?;let stamp=SavedFileStamp::from_bytes(loaded.session.snapshot().revision(),&bytes);let loaded=crate::image_slideshow::directories::refresh_loaded(loaded).map_err(native)?;Ok(Opened{loaded:Box::new(loaded),path,view:index.view(root),id,stamp,creation:None})}
/// Only serializes a managed native save with cooperating library mutations;
/// index labels are updated AFTER GUI accepts its ordinary save receipt.
pub fn save_native(root:Option<&Root>,job:SaveJob)->Result<SaveReceipt,Error>{let Some(root)=root else{return job.run().map_err(native);};let reserved=job.path().file_name().and_then(|name|name.to_str()).and_then(|name|name.strip_suffix(".skylive.json")).is_some_and(|name|name.len()==16&&name.bytes().all(|byte|byte.is_ascii_hexdigit()));if !reserved{return job.run().map_err(native);}let absolute=std::path::absolute(job.path()).map_err(io_before)?;let Some(actual)=(match root.actual(false){Ok(value)=>value,Err(error)if absolute.parent()==Some(root.path())=>return Err(error),Err(_)=>return job.run().map_err(native)})else{return job.run().map_err(native);};let parent=absolute.parent().and_then(|parent|fs::canonicalize(parent).ok());if parent.as_deref()!=Some(actual.as_path()){return job.run().map_err(native);}let index=read_index(&actual)?;if !index.entries.iter().any(|entry|entry_path(&actual,entry.id).file_name()==job.path().file_name()){return job.run().map_err(native);}let _lock=Lock::acquire(&actual)?;let current=read_index(&actual)?;let Some(target)=current.entries.iter().find(|entry|entry_path(&actual,entry.id).file_name()==job.path().file_name())else{return Err(reject("collection_stale","managed collection was removed before native save"));};if current.entries.iter().any(|entry|entry.id!=target.id&&entry.name==job.collection_name()){return Err(reject("collection_name_conflict","choose a unique collection name before saving this managed target"));}job.run().map_err(native)}
/// An accepted document Save is a separate fact from this index-label write.
/// Same-name/revision but changed bytes cannot inherit an old delayed label.
pub fn sync_saved_name(root:&Root,path:&Path,name:&str,stamp:SavedFileStamp)->Result<Option<View>,Error>{validate_name(name)?;let Some(actual)=root.actual(false)?else{return Ok(None);};let parent=path.parent().and_then(|parent|fs::canonicalize(parent).ok());if parent.as_deref()!=Some(actual.as_path()){return Ok(None);}let _lock=Lock::acquire(&actual)?;let mut index=read_index(&actual)?;let Some(position)=index.entries.iter().position(|entry|entry_path(&actual,entry.id).file_name()==path.file_name())else{return Ok(None);};let owned=entry_path(&actual,index.entries[position].id);direct_child(&actual,&owned)?;regular_file(&owned)?;let bytes=storage::read_bytes(&owned).map_err(native)?;if !stamp.matches(&bytes){return Err(reject("collection_stale_save","saved native file changed before library name synchronization"));}if index.entries.iter().enumerate().any(|(i,entry)|i!=position&&entry.name==name){return Err(reject("collection_name_conflict","native file saved, but another managed collection uses its new name"));}if index.entries[position].name!=name{index.entries[position].name=name.to_owned();index.bump()?;publish_index(&actual,&index)?;}Ok(Some(index.view(actual)))}
#[derive(Clone)]pub struct RemovePlan{root:Root,id:EntryId,path:PathBuf,stamp:SavedFileStamp}
impl RemovePlan{pub fn id(&self)->EntryId{self.id}pub fn path(&self)->&Path{&self.path}pub fn refresh_accepted_save(&mut self,path:&Path,stamp:SavedFileStamp){if self.path==path{self.stamp=stamp;}}}
pub struct RemovalPrepared{pub alternative:Opened,pub removal:RemovePlan}
pub fn prepare_remove(view:&View,current:&Path)->Result<RemovalPrepared,Error>{let root=view.root.actual(false)?.ok_or_else(||reject("collection_root","managed root is unavailable"))?;let index=read_index(&root)?;if index.entries.len()<2{return Err(reject("collection_last","the last managed collection cannot be removed"));}let current=fs::canonicalize(current).map_err(io_before)?;let entry=index.entries.iter().find(|entry|entry_path(&root,entry.id)==current).ok_or_else(||reject("collection_external","only an indexed managed collection can be removed"))?;regular_file(&current)?;direct_child(&root,&current)?;let bytes=storage::read_bytes(&current).map_err(native)?;let loaded=storage::decode_with_report(&bytes,true).map_err(native)?;let stamp=SavedFileStamp::from_bytes(loaded.session.snapshot().revision(),&bytes);drop(loaded);drop(bytes);let ordered=index.view(root.clone());let next=ordered.entries.iter().find(|next|next.id!=entry.id).ok_or_else(||reject("collection_last","another managed collection is required"))?;let alternative=open(&ordered,next.id)?;Ok(RemovalPrepared{alternative,removal:RemovePlan{root:Root{path:root},id:entry.id,path:current,stamp}})}
pub struct Removed{pub view:View,pub recovery:PathBuf,pub cleanup_problem:Option<String>}
pub fn remove(plan:RemovePlan,active:&Path)->Result<Removed,Error>{let root=plan.root.actual(false)?.ok_or_else(||reject("collection_root","managed root is unavailable"))?;let _lock=Lock::acquire(&root)?;let mut index=read_index(&root)?;if index.entries.len()<2||!index.entries.iter().any(|entry|entry.id==plan.id){return Err(reject("collection_stale","managed collection set changed before removal"));}let owned=entry_path(&root,plan.id);direct_child(&root,&owned)?;regular_file(&owned)?;let source=fs::canonicalize(&owned).map_err(io_before)?;if source!=plan.path||source.parent()!=Some(root.as_path()){return Err(reject("collection_path","resolved removal source is outside the approved owned path"));}let active=fs::canonicalize(active).map_err(io_before)?;if active==source{return Err(reject("collection_active","publish another collection before removing the current one"));}let bytes=storage::read_bytes(&source).map_err(native)?;if !plan.stamp.matches(&bytes){return Err(reject("collection_changed","owned native artifact changed after removal was prepared"));}drop(bytes);
 let trash=root.join("trash");direct_child(&root,&trash)?;fs::create_dir_all(&trash).map_err(io_before)?;let trash=fs::canonicalize(trash).map_err(io_before)?;if trash.parent()!=Some(root.as_path()){return Err(reject("collection_path","resolved recovery directory is outside the owned root"));}index.bump()?;let recovery=trash.join(format!("{:016x}-{:016x}.skylive.json",plan.id.0,index.version));direct_child(&trash,&recovery)?;
 // A no-clobber recovery link precedes detachment. Original stays intact until
 // index publication succeeds. No recursive delete/move or guessed rollback.
 fs::hard_link(&source,&recovery).map_err(|error|reject("collection_recovery_link",format!("{} -> {}: {error}",source.display(),recovery.display())))?;index.entries.retain(|entry|entry.id!=plan.id);publish_index(&root,&index).map_err(|error|partial("collection_remove_partial",format!("recovery retained; index publication failed and original was not unlinked: {error}"),recovery.clone()))?;let cleanup_problem=fs::remove_file(&source).err().map(|error|format!("library entry removed; recovery at {}; original retained at {}: {error}",recovery.display(),source.display()));Ok(Removed{view:index.view(root),recovery,cleanup_problem})}

/// Unpublished native-open context. Only document_repair's IO owner may turn
/// this into a public Opened receipt after strict materialization and recheck.
pub(crate) struct RepairContext{pub(crate) path:PathBuf,root:Root,id:EntryId,view:View,stamp:SavedFileStamp,removal:Option<RemovePlan>}
impl RepairContext{
 pub(crate) fn has_removal(&self)->bool{self.removal.is_some()}
 pub(crate) fn recheck(&mut self)->Result<(),Error>{let actual=self.root.actual(false)?.ok_or_else(||reject("collection_root","managed repair root is unavailable"))?;let index=read_index(&actual)?;if !index.entries.iter().any(|entry|entry.id==self.id){return Err(reject("collection_stale","managed repair identity no longer exists"));}let owned=entry_path(&actual,self.id);direct_child(&actual,&owned)?;regular_file(&owned)?;if owned!=self.path{return Err(reject("collection_path","managed repair path changed"));}let bytes=storage::read_bytes(&owned).map_err(native)?;if !self.stamp.matches(&bytes){return Err(reject("collection_changed","managed native artifact changed while its resources were repaired"));}self.view=index.view(actual);Ok(())}
 pub(crate) fn accepted_save(&mut self,path:&Path,stamp:SavedFileStamp){if let Some(plan)=&mut self.removal{plan.refresh_accepted_save(path,stamp);}}
 pub(crate) fn project(&self,loaded:LoadedDocument)->(Opened,Option<RemovePlan>){(Opened{loaded:Box::new(loaded),path:self.path.clone(),view:self.view.clone(),id:self.id,stamp:self.stamp,creation:None},self.removal.clone())}
}
pub(crate) fn read_for_repair(view:&View,id:EntryId)->Result<(LoadedDocument,RepairContext),Error>{
 let root=view.root.actual(false)?.ok_or_else(||reject("collection_root","managed root is missing"))?;let index=read_index(&root)?;if !index.entries.iter().any(|entry|entry.id==id){return Err(reject("collection_stale","managed collection identity no longer exists"));}let path=entry_path(&root,id);direct_child(&root,&path)?;regular_file(&path)?;
 let bytes=storage::read_bytes(&path).map_err(native)?;let loaded=storage::decode_with_report(&bytes,true).map_err(native)?;let stamp=SavedFileStamp::from_bytes(loaded.session.snapshot().revision(),&bytes);let view=index.view(root.clone());Ok((loaded,RepairContext{path,root:Root{path:root},id,view,stamp,removal:None}))
}
pub(crate) fn read_removal_for_repair(view:&View,current:&Path)->Result<(LoadedDocument,RepairContext),Error>{
 let root=view.root.actual(false)?.ok_or_else(||reject("collection_root","managed root is unavailable"))?;let index=read_index(&root)?;if index.entries.len()<2{return Err(reject("collection_last","the last managed collection cannot be removed"));}let current=fs::canonicalize(current).map_err(io_before)?;let entry=index.entries.iter().find(|entry|entry_path(&root,entry.id)==current).ok_or_else(||reject("collection_external","only an indexed managed collection can be removed"))?;regular_file(&current)?;direct_child(&root,&current)?;
 let bytes=storage::read_bytes(&current).map_err(native)?;let loaded=storage::decode_with_report(&bytes,true).map_err(native)?;let stamp=SavedFileStamp::from_bytes(loaded.session.snapshot().revision(),&bytes);drop(loaded);drop(bytes);
 let ordered=index.view(root.clone());let next=ordered.entries.iter().find(|next|next.id!=entry.id).ok_or_else(||reject("collection_last","another managed collection is required"))?;let(loaded,mut context)=read_for_repair(&ordered,next.id)?;context.removal=Some(RemovePlan{root:Root{path:root},id:entry.id,path:current,stamp});Ok((loaded,context))
}
